import fs from 'node:fs/promises';
import path from 'node:path';

// Persistent, single-user bookmark collection backed by a JSON file.
// Newest bookmarks are kept at the front of the list.

const ALLOWED_FIELDS = ['url', 'title', 'site', 'desc', 'tags', 'note', 'readLater', 'archived'];

function cleanTags(tags) {
  if (!Array.isArray(tags)) return [];
  return tags.map(t => String(t).trim()).filter(Boolean);
}

function newBookmark(input, id) {
  return {
    id,
    url: String(input.url || '').trim(),
    title: String(input.title || '').trim() || String(input.url || '').trim(),
    site: String(input.site || '').trim(),
    desc: String(input.desc || '').trim(),
    tags: cleanTags(input.tags),
    note: String(input.note || '').trim(),
    readLater: Boolean(input.readLater),
    archived: Boolean(input.archived),
    createdAt: new Date().toISOString()
  };
}

function sanitizeUpdate(input) {
  const out = {};
  for (const key of ALLOWED_FIELDS) {
    if (!(key in input)) continue;
    if (key === 'tags') out.tags = cleanTags(input.tags);
    else if (key === 'readLater' || key === 'archived') out[key] = Boolean(input[key]);
    else out[key] = String(input[key] ?? '').trim();
  }
  return out;
}

export class Store {
  constructor(file) {
    this.file = file;
    this.data = { bookmarks: [], nextId: 1 };
  }

  async init() {
    try {
      const raw = await fs.readFile(this.file, 'utf8');
      const parsed = JSON.parse(raw);
      this.data.bookmarks = Array.isArray(parsed.bookmarks) ? parsed.bookmarks : [];
      this.data.nextId = Number.isInteger(parsed.nextId) ? parsed.nextId : this._computeNextId();
    } catch {
      this.data = { bookmarks: [], nextId: 1 };
      await this._persist();
    }
    return this;
  }

  _computeNextId() {
    return this.data.bookmarks.reduce((m, b) => Math.max(m, b.id), 0) + 1;
  }

  async _persist() {
    await fs.mkdir(path.dirname(this.file), { recursive: true });
    await fs.writeFile(this.file, JSON.stringify(this.data, null, 2));
  }

  all() {
    return this.data.bookmarks;
  }

  get(id) {
    return this.data.bookmarks.find(b => String(b.id) === String(id)) || null;
  }

  async create(input) {
    const b = newBookmark(input, this.data.nextId++);
    this.data.bookmarks.unshift(b);
    await this._persist();
    return b;
  }

  async update(id, input) {
    const b = this.get(id);
    if (!b) return null;
    Object.assign(b, sanitizeUpdate(input));
    await this._persist();
    return b;
  }

  async remove(id) {
    const i = this.data.bookmarks.findIndex(b => String(b.id) === String(id));
    if (i === -1) return false;
    this.data.bookmarks.splice(i, 1);
    await this._persist();
    return true;
  }

  async reset() {
    this.data = { bookmarks: [], nextId: 1 };
    await this._persist();
  }
}
// Fetch a link's page and extract basic details (title, description, site name).
// A failure to reach the page throws; callers translate that into the
// "couldn't get details" behaviour so saving is never blocked.

const ENTITIES = { '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'", '&apos;': "'", '&nbsp;': ' ' };

function decode(s) {
  return s.replace(/&amp;|&lt;|&gt;|&quot;|&#39;|&apos;|&nbsp;/g, m => ENTITIES[m])
          .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)));
}

function titleCase(host) {
  const core = host.replace(/^www\./, '').split('.')[0];
  return core ? core.charAt(0).toUpperCase() + core.slice(1) : host;
}

function firstMatch(html, patterns) {
  for (const re of patterns) {
    const m = html.match(re);
    if (m && m[1] && m[1].trim()) return m[1];
  }
  return '';
}

// Exported for unit testing without network access.
export function parseMetadata(html, url) {
  const host = new URL(url).hostname.replace(/^www\./, '');
  const title = firstMatch(html, [
    /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i,
    /<title[^>]*>([\s\S]*?)<\/title>/i
  ]) || titleCase(host);
  const desc = firstMatch(html, [
    /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i,
    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i
  ]);
  const site = firstMatch(html, [
    /<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)["']/i
  ]) || titleCase(host);
  return {
    site: decode(site.trim()),
    title: decode(title.trim().replace(/\s+/g, ' ')),
    desc: decode(desc.trim().replace(/\s+/g, ' '))
  };
}

export async function fetchMetadata(url, { timeoutMs = 8000, fetchImpl = fetch } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  let resp;
  try {
    resp = await fetchImpl(url, {
      signal: controller.signal,
      redirect: 'follow',
      headers: { 'user-agent': 'BookmarksApp/1.0 (+details fetch)' }
    });
  } finally {
    clearTimeout(timer);
  }
  if (!resp.ok) throw new Error('HTTP ' + resp.status);
  const html = await resp.text();
  return parseMetadata(html, url);
}
